import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"兌下坤上 臨：","description":"京氏易傳 - 兌下坤上 臨：","frontmatter":{"title":"兌下坤上 臨：","description":"京氏易傳 - 兌下坤上 臨："},"headers":[],"relativePath":"classics/jingshi/036.md","filePath":"classics/jingshi/036.md"}'),i={name:"classics/jingshi/036.md"};function r(c,a,o,p,d,m){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"兌下坤上-臨",tabindex:"-1"},[l("兌下坤上 臨： "),e("a",{class:"header-anchor",href:"#兌下坤上-臨","aria-label":"Permalink to “兌下坤上 臨：”"},"​")],-1),e("p",null,"陽長陰消悅而順，金土應候剛柔分。震入兌，二陽剛，本體陰柔降入臨。臨者，大也。陽爻健順，陽交退散。《易》曰：“君子之道”。《易》雲：“至於八月有兇”。（虎易注：此處脫漏有字。）【建醜至未也。】陽長，六爻反覆，吉凶之道可見矣。【至於八月入遁。】與兌為飛伏，【丁卯木，乙巳火。】九二大夫立世，六五至尊應上位。",-1),e("p",null,"建始丙申至辛丑，【立秋，大寒。】七月積氣至六月，吉凶隨爻考汙隆。【旺則隆，衰則汙。】積算起辛丑至庚子。【積算起金土入卦，推休咎於六爻。】",-1),e("p",null,"五星從位起熒惑，【熒惑火星，入卦用事。】翼宿從位在丁卯，【二十八宿，翼宿入卦九二爻木上。】分氣候三十六。【定陰陽之數，起於三十六積算。】",-1),e("p",null,"坤下見兌，悅、澤，臨。陽升陰降，入三陽，乾象入坤，即泰卦。【臨卦內象先陽長，逼陰成乾為泰象。】外坤積陰，內兌亦為陰，二陽合體，柔順之道，不可貞。吉凶以時，配於六位，用於陽長之爻，成臨之義。",-1),e("p",null,"六三將變陽爻，至次降入泰卦。【次入地天泰卦。】",-1)])])}const f=s(i,[["render",r]]);export{_ as __pageData,f as default};
